        return sum(numbers) / len(numbers)

    # Function to calculate the median  
    def calculate_median(self, numbers):
        numbers.sort()
        mid_point = int(len(numbers) / 2)
        if len(numbers) % 2 == 0:
            return (numbers[mid_point - 1] + numbers[mid_point]) / 2
        else: 
            return numbers[mid_point]

